import js from '@eslint/js';
import globals from 'globals';
import react from 'eslint-plugin-react';
import reactHooks from 'eslint-plugin-react-hooks';
import prettier from 'eslint-config-prettier';

const noUnusedVars = [
  'error',
  { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrors: 'none' },
];

export default [
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      'server/data/**',
      'docs/**',
      // Generated by client/studio/build.mjs.
      'client/public/studio/**',
      // vLabs Template Studio's page scripts: they share one scope once
      // concatenated by client/studio/build.mjs, so they are not separate
      // modules to lint one by one.
      'client/studio/src/{imports,exam-core,lab-core,studio,exam-ui,host}.js',
    ],
  },

  js.configs.recommended,

  // ---- Server + shared: Node + ESM ---------------------------------------
  {
    files: ['server/**/*.js', 'shared/**/*.js'],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.node },
    },
    rules: {
      'no-unused-vars': noUnusedVars,
    },
  },

  // ---- Client: browser + React + JSX ------------------------------------
  {
    files: ['client/src/**/*.{js,jsx}'],
    plugins: { react, 'react-hooks': reactHooks },
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      // __APP_VERSION__ is injected by Vite's `define` (client/vite.config.js).
      globals: { ...globals.browser, __APP_VERSION__: 'readonly' },
      parserOptions: { ecmaFeatures: { jsx: true } },
    },
    settings: { react: { version: '18.3' } },
    rules: {
      ...react.configs.flat.recommended.rules,
      ...reactHooks.configs.recommended.rules,
      // The automatic JSX runtime means React need not be in scope.
      'react/react-in-jsx-scope': 'off',
      'react/prop-types': 'off',
      // Apostrophes in user-facing copy are intentional, not markup bugs.
      'react/no-unescaped-entities': 'off',
      'no-unused-vars': noUnusedVars,
    },
  },

  // ---- vLabs Template Studio: the bundled modules (browser) ---------------
  {
    files: ['client/studio/src/*.js'],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.browser },
    },
    rules: {
      'no-unused-vars': noUnusedVars,
    },
  },

  // ---- Client unit tests run under node:test ----------------------------
  {
    files: ['client/tests/**/*.js'],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.node },
    },
    rules: {
      'no-unused-vars': noUnusedVars,
    },
  },

  // ---- Config files + repo scripts run under Node -----------------------
  {
    files: ['**/*.config.js', 'eslint.config.js', 'scripts/**/*.js', 'client/studio/*.mjs'],
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: { ...globals.node },
    },
  },

  // Disable stylistic rules that Prettier owns.
  prettier,
];
